for name,file in [('ELS','DejaVuSans.ttf'),('ELB','DejaVuSans-Bold.ttf'),('ELT','DejaVuSerif.ttf')]:pdfmetrics.registerFont(TTFont(name,'/usr/share/fonts/truetype/dejavu/'+file))
ink=colors.HexColor('#243d35');green=colors.HexColor('#e7efe7');line=colors.HexColor('#bfcbbf')
styles={k:ParagraphStyle(k,fontName=font,fontSize=size,leading=leading,textColor=ink,spaceAfter=after) for k,font,size,leading,after in [('title','ELT',24,29,14),('body','ELS',9.4,14,9),('small','ELS',7.5,11,5),('heading','ELB',12,17,9),('table','ELS',8,11.5,0)]}
def P(s,k='body'):return Paragraph(escape(str(s)).replace('\n','<br/>'),styles[k])
def footer(c,doc):c.setFont('ELS',7);c.setFillColor(ink);c.drawString(42,24,'Growing Together · Original Early Learning Curriculum · Birth through age six');c.drawRightString(A4[0]-42,24,str(doc.page))
def export_book(name,pages):
 story=[];doc=Document();sec=doc.sections[0];sec.top_margin=Inches(.65);sec.bottom_margin=Inches(.65);sec.left_margin=Inches(.65);sec.right_margin=Inches(.65);normal=doc.styles['Normal'];normal.font.name='Calibri';normal.font.size=Pt(10);normal.paragraph_format.space_after=Pt(7)
 for i,page in enumerate(pages):
  if i:story.append(PageBreak());doc.add_page_break()
  story.append(P(page['title'],'title'));doc.add_heading(page['title'],0)
  for block in page['blocks']:
   kind=block[0]
   if kind in ['p','small','h']:
    text=block[1];story.append(P(text,{'p':'body','small':'small','h':'heading'}[kind]));doc.add_heading(text,2) if kind=='h' else doc.add_paragraph(text)
   elif kind=='table':
    headers,rows,widths=block[1:];data=[[P(x,'table') for x in headers]]+[[P(x,'table') for x in row] for row in rows];t=Table(data,colWidths=widths,repeatRows=1,hAlign='LEFT');t.setStyle(TableStyle([('GRID',(0,0),(-1,-1),.35,line),('BACKGROUND',(0,0),(-1,0),green),('VALIGN',(0,0),(-1,-1),'TOP'),('TOPPADDING',(0,0),(-1,-1),6),('BOTTOMPADDING',(0,0),(-1,-1),6)]));story.append(t);story.append(Spacer(1,9));table=doc.add_table(rows=1,cols=len(headers));table.style='Table Grid'
    for cell,text in zip(table.rows[0].cells,headers):cell.text=text
    for row in rows:
     for cell,text in zip(table.add_row().cells,row):cell.text=str(text)
   elif kind=='lines':
    label,n=block[1:];story.append(P(label,'heading'));t=Table([['']]*n,colWidths=[500],rowHeights=22);t.setStyle(TableStyle([('LINEBELOW',(0,0),(-1,-1),.35,line)]));story.append(t);story.append(Spacer(1,8));doc.add_heading(label,2)
    for _ in range(n):doc.add_paragraph('_'*75)

 pdf=SimpleDocTemplate(str(R/(name+'.pdf')),pagesize=A4,leftMargin=42,rightMargin=42,topMargin=38,bottomMargin=42,title='Growing Together — '+name.replace('_',' '),author='Growing Together');pdf.build(story,onFirstPage=footer,onLaterPages=footer);doc.save(R/(name+'.docx'))
 return len(pages)
def page(title,*blocks):return {'title':title,'blocks':list(blocks)}
pages=[]
pages.append(page('Growing Together',[ 'p','An original childcare-center learning curriculum from birth through age six. The final pathway includes 5- and 6-year-olds, through 83 months.'],['h','A whole-child, play-based organization'],['p','Warm relationships and responsive care are the foundation. Infants learn through everyday interaction, safe movement and care. Toddlers explore concrete materials and familiar routines. Older children combine sustained play and inquiry with meaningful explicit teaching. Children can participate through movement, gesture, speech, signs, augmentative communication, observation and adapted action.'],['h','What is included'],['p','Seven age pathways; seven connected learning areas; 98 original activity plans; twelve inquiry connections organized into 48 flexible planning slots; daily flow examples; planning and observation forms; and a self-contained browser tool. Four additional weeks of a 52-week calendar remain available for closures, transitions, repetition or local priorities.'],['h','Research status — read before implementation'],['p','The request was to use popular U.S. curricula as a research starting point. Live search and all ten reference requests were blocked by the environment’s network proxy, including public government, professional and publisher sites. A current nationwide popularity ranking and current primary-source review were not verified. This is an original professional draft based on general established early-childhood knowledge, not a completed live literature review.'],['p','The Creative Curriculum, HighScope and Frog Street are recognizable curriculum families for later comparison. No market-share numbers, ranking, endorsement or claim that this resource reproduces any of them is made.'],['small','Edition 1.0 · Prepared for review on '+str(datetime.datetime.now(ZoneInfo('America/Los_Angeles')).date())+' · Local standards, health procedures, individualized plans and trained staff review remain part of implementation.']))
pages.append(page('Why this teaching approach',['p','The curriculum uses a play-based, whole-child structure because it can organize a full childcare day across infancy, toddlerhood, preschool and the kindergarten years. Responsive interaction, intentional teaching and child-led inquiry are complementary teaching moves. No one move is suitable for every purpose or age.'],['table',['Reference family / approach','Broad organizing idea','How this original draft uses the idea'],[['The Creative Curriculum','Comprehensive whole-child curriculum family. Current product details were not retrieved.','Keep learning areas, routines, environment and assessment connected without copying commercial lessons.'],['HighScope','Active participatory learning and intentional adult support. Current source not retrieved.','Offer choice, meaningful action and reflection at an accessible level.'],['Frog Street','Recognizable early-childhood curriculum family. Current source not retrieved.','Use a coherent center-wide organization while retaining child/family responsiveness.'],['Inquiry / project learning','Questions can develop through revisiting materials, evidence and representation.','Use flexible inquiry connections for older children; do not impose projects on infants.'],['Responsive, developmentally appropriate teaching','Individual, family and contextual knowledge inform interaction. Reference routes not retrieved.','Adjust to cues, strengths, access, home languages and care needs rather than age-only tasks.']],[115,170,215]],['p','These are descriptive comparisons, not a popularity table or a verified product evaluation. The resource is original and is not licensed, affiliated with or endorsed by the named programs. A later source-based review should compare age coverage, evidence, training, family access, adaptations, cost and observation methods before a center purchases a commercial curriculum.']))
pages.append(page('The teaching commitments',['h','Connect before directing'],['p','Know the child and the family. Learn the names, languages, communication forms, comfort preferences and supports that make participation possible. An adult’s availability and predictable response are learning conditions, not rewards.'],['h','Protect care, movement and sustained play'],['p','Needed feeding, rest, hygiene, comfort and health care are never delayed to finish an activity. Infants follow individual cues and plans. For older children, plan long enough for meaningful self-chosen play, outdoor movement and creative work alongside useful short teaching invitations.'],['h','Teach intentionally without taking over'],['p','Choose an action that fits the purpose: wait, describe, demonstrate, offer vocabulary, model a strategy, ask a genuine question, add a useful material or step back. Explicit instruction in a needed tool can sit inside play and projects. Repeated testing, copying and worksheets are not the organizing core.'],['h','Let evidence change the plan'],['p','A good activity may be declined. Record what actually happened and adapt the invitation, materials, timing or adult support. Repetition of familiar work is productive. A child’s choice to watch or communicate differently is participation, not evidence of inability.'],['h','Avoid age-only expectations'],['p','Pathways organize possible environments and experiences. They are not milestone checklists, readiness gates or requirements to complete every activity. Co-regulation and adapted access remain legitimate supports at every age.']))
pages.append(page('Seven connected learning areas',['table',['Area','Purpose','Illustrative framework connection'],[[a['title'],a['goal'],a['frameworkConnection']] for a in d['areas']],[115,195,190]],['p','Attention, interest, persistence, flexibility, help seeking and accessible communication cut across every area. Art and community learning are integrated experiences, not optional rewards after academic work.'],['small','The connection column is an author-created organizational crosswalk using familiar Head Start ELOF domain terms. The framework could not be retrieved in this session; no code-by-code, current-edition or official alignment is claimed. ELOF is a birth-to-five reference, and the kindergarten bridge needs separate local/school review.']))
pages.append(page('Prepare a usable environment',['p','Arrange safe, accessible choices so children can participate, repeat and restore with appropriate help. A center-wide curriculum does not mean infants and older children share unsafe materials or the same activity timetable.'],['table',['Environment feature','Adult preparation'],[['Relationships','Keep responsive familiar caregivers available. Plan calm handoffs and hear family information.'],['Movement and floor access','Provide clear safe space, stable positioning and mobility access. Do not force sitting, crawling, standing or a standard body position.'],['Materials','Inspect size, integrity, hygiene, sensory access and intended use. Keep small parts, sharp tools and older-child materials inaccessible to younger children.'],['Communication','Include home-language books, photos used with consent, signs, visuals and augmentative communication as appropriate.'],['Choice and quiet','Offer manageable choices and a route to a quieter or different experience without isolation or punishment.'],['Outdoor learning','Review weather, sun, air quality, boundaries, plants, surfaces and accessible movement options.'],['Work in progress','Preserve older children’s projects when practical. Photographs or work samples need consent and secure storage.']],[130,370]],['p','Use an approved safety review before introducing an unusual material, tool, food activity, water experience or experiment. The activity library is not permission to bypass care, supervision or individual plans.']))
pages.append(page('Language, access and belonging',['p','Include the child’s strongest communication and the languages used at home. A child may demonstrate understanding by gesture, drawing, movement, signs, a device, another language or supported action. English-only speech and eye contact are not participation requirements.'],['h','Plan adaptations before the invitation'],['p','Ask what sensory, movement, hearing, vision, communication and regulation access is needed. Offer a stable surface, alternate grip, visual sequence, extra processing time, quieter materials, a larger object or another way to respond. Adjust the challenge while preserving a meaningful purpose.'],['h','Represent families accurately'],['p','Use varied family structures, homes, abilities, languages, occupations and community experiences. Ask for a specific voluntary contribution rather than asking a family or child to represent an entire culture. Do not require photographs, religious disclosure, purchases, donations or public performance.'],['h','Respond to behavior as information'],['p','Describe the event, context and support. Stop harm, meet the immediate need and help children communicate or try a workable solution. Avoid character labels, public behavior rankings, forced apologies or withholding care. Do not ask children to negotiate unsafe treatment.'],['h','Keep professional decisions in the proper process'],['p','Curriculum observations can inform a conversation; they do not diagnose, replace validated screening or determine eligibility for support. Use the program’s approved family/referral and individualized-planning processes when a concern persists.']))
pages.append(page('Care and safety anchors',['h','Infants: responsive care and safe sleep'],['p','Use individual cues and approved care plans for feeding, rest, comfort and hygiene. Awake floor activity is separate from sleep. Tummy-time invitations are awake, directly supervised and adapted to comfort. Put infants on their backs for every sleep on the approved firm flat clear sleep surface, following current health procedures. No activity materials, loose cloth, toys or weighted items belong in the sleep space.'],['h','Every pathway'],['p','Adults check choking and mouthing risks, water, tools, allergies, heat, hygiene, outdoor conditions and individual access before an invitation. Direct supervision is essential for water, food preparation and tool activities. Empty water containers afterward and dry wet floors. Adults handle chemicals, hazardous spills, unknown plants, wildlife hazards and unsafe equipment.'],['h','Respect the child’s body and dignity'],['p','Do not force tasting, touch, eye contact, speech, a posture or an emotional performance. Support toileting with families and approved health practices; do not make toileting or disability-related independence a readiness test. Offer appropriate rest/quiet options and follow actual program/state procedures.'],['h','What this curriculum does not replace'],['p','Attendance, medication, feeding/health orders, illness, incident, safeguarding, emergency and legally required records stay in approved systems. Learning notes are not a substitute. This publication does not set staffing ratios or certify compliance with state/local rules.'],['small','Health-reference routes to verify before implementation are documented in the research log: AAP/HealthyChildren, CDC and Caring for Our Children. They could not be retrieved during authoring, so staff should review current authoritative guidance and local requirements.']))
pages.append(page('Observe → plan → revisit',['table',['Step','Useful action','Record'],[['Observe','Watch the actual event and receive family information.','What was seen/heard; context; date; access/support.'],['Interpret cautiously','Consider possibilities without turning a guess into a fact.','A working question, separate from the observation.'],['Plan','Choose a purpose and a few safe accessible invitations.','Why this invitation; materials; adaptation; actual child/group.'],['Join','Respond, model, ask, describe or step back.','Support actually given and the child’s response.'],['Review','Revisit evidence across time and contexts.','A possible next opportunity and what might change.']],[75,215,210]],['p','Useful note: “Matched one cup to each of five people, then counted after one reminder.” Less useful: “Mastered math.” Useful infant note: “Turned away after the third sound. Adult paused; infant relaxed and looked back.” Less useful: “Poor attention.”'],['p','The tool’s statuses describe interest, an offered invitation, exploration/practice, a strategy used independently in one observation, or a plan to adjust. They are not scores or permanent mastery labels. Independent performance is not an infant goal; responsive adult help is part of the learning environment.'],['p','Review learning across areas without turning coverage into a quota. A blank record is not a learning gap. A declined activity may indicate timing, access, preference or another need, and does not alone establish a developmental concern.']))
pages.append(page('A workable staff planning rhythm',['h','Before the day'],['p','Review family information and essential approved care plans; inspect the environment; choose a few possible invitations connected to actual observations. Keep familiar materials available and identify adaptations or supervision needs.'],['h','During the day'],['p','Protect responsive care, child-chosen play and useful conversation. One adult’s documentation should never reduce supervision. Short notes can be completed securely later. Record the factual event before writing an interpretation.'],['h','At the end of the day'],['p','Finish concise observations, restore materials and adjust the next invitation. Share a meaningful strength or event with families through the approved communication route. Record operational health/safety matters in their proper systems.'],['h','Weekly team review'],['p','Ask whose voice is missing, which support helped, which plan no longer fits, where evidence is thin and which family perspective would help. Choose a manageable next step instead of adding many activities. Export a secure backup of the local planning tool.'],['h','Initial implementation'],['p','Start with one or two familiar invitations per pathway, not the whole library. Practice factual note writing and review safety/access with trained staff. Use a brief pilot, family feedback and peer review before making center-wide changes. Confirm state standards and current reference guidance when access is available.']))
